def fibonacci(n):
"""
Return the nth Fibonacci number (0-indexed).
Raises ValueError for negative inputs.
"""
if n < 0:
raise ValueError("n must be non-negative")
a, b = 0, 1
for _ in range(n):
a, b = b, a + b
return a
if __name__ == "__main__":
# Test cases
for i in range(10):
print(f"Fibonacci({i}) = {fibonacci(i)}")

